/**
 * VEER (Indy/Hoosier) — varsity page 5 (main diagram + assignment table) and
 * page 6 (vs Even / vs Odd, both directions).
 *
 * Veer Red runs to the RIGHT and is hand-authored from the scans. Veer Black
 * is the mirror of it (page 1 draws Black as Red's mirror), generated by
 * `mirrorPlay` with the overrides stated at the bottom of this file.
 *
 * Resolving varsity's playside/backside rows to actual players, Red right:
 *   PST = RT · PSG = RG · C = C · BSG = LG · BST = LT
 *   PSW = R (playside wing) · BSW = L (backside wing — the PITCH MAN)
 *   Y = backside tight end · X = playside split end
 *   S = dive back · Q = quarterback
 *
 * The read key is the first down defender ON or OUTSIDE the playside tackle:
 * vs our even fronts that's the end (`E-R`); vs the 5-2 it's the tackle head
 * up on the RT (`T-R`), which is why the 5-2 diagram looks different.
 */

import type {
  Action,
  Assignment,
  FrontId,
  FrontPlan,
  OffPosId,
  Play,
} from '../../types/football'
import { mirrorPlay } from '../../utils/mirror'

/** A block aimed at a defender — no path, so it can never strand a diagram. */
const block = (targetId: string): Action[] => [{ kind: 'block', targetId }]

// ---------------------------------------------------------------------------
// Skill actions — identical against all three fronts.
// ---------------------------------------------------------------------------

/** S: dive at the crack (inside leg) of the playside guard, mesh with Q. */
const S_DIVE: Action[] = [
  {
    kind: 'carry',
    path: [
      { x: 0.5, y: -2.8 },
      { x: 1, y: -1.2 },
      { x: 1.3, y: 0.3 },
      { x: 1.7, y: 3 },
      { x: 2, y: 6 },
    ],
  },
]

/** Q: step playside, ride the mesh, keep vertical in the C gap. */
const Q_READ: Action[] = [
  {
    kind: 'run',
    path: [
      { x: 1, y: -1.7 },
      { x: 2.4, y: -1.6 },
      { x: 3.8, y: -0.8 },
      { x: 4.8, y: 1 },
      { x: 5.2, y: 3.5 },
    ],
  },
]

/**
 * L: the squiggle on the scan. Pre-snap motion through the heels of Super,
 * then arc out and stay 5 yards outside / 1 yard behind the quarterback.
 */
const L_PITCH: Action[] = [
  {
    kind: 'motion',
    path: [
      { x: -4, y: -2.6 },
      { x: -2, y: -4.2 },
      { x: 0, y: -5 },
      { x: 2, y: -4.6 },
      { x: 3.8, y: -3.8 },
    ],
  },
  {
    kind: 'pitch',
    path: [
      { x: 5.6, y: -2.8 },
      { x: 7.6, y: -1.4 },
      { x: 9, y: 0.6 },
    ],
  },
]

/** X: playside — go get the corner. */
const X_CORNER: Action[] = block('C-R')

/** R: tight off the read key's hip before he pins anybody. */
const WING_TIGHT: Action = {
  kind: 'run',
  path: [
    { x: 5, y: 0.4 },
    { x: 5.6, y: 1.8 },
  ],
}

const SKILL = {
  S: S_DIVE,
  Q: Q_READ,
  L: L_PITCH,
  X: X_CORNER,
} satisfies Partial<Record<OffPosId, Action[]>>

/**
 * LT on Rip vs an even front. The scan (p5, and p6's "vs Even" panel) draws his
 * first move as a step DOWN THE LINE into the guard's spot — he ends up almost
 * standing where LG lined up — and only from there does he climb to the
 * backside backer. Authoring that first step keeps the arrow pointing inside
 * instead of leaking out toward the end.
 */
const LT_RIP: Action[] = [
  { kind: 'run', path: [{ x: -1.9, y: 0.3 }] },
  ...block('B-L'),
]

// ---------------------------------------------------------------------------
// Line work shared by the two EVEN fronts (4-4 and 4-3).
//   Backside: LG has the down man on him, LT steps down into the guard's spot
//             and climbs to the backside backer, Y rips inside and walls the
//             backside end.
//   Playside: RG bases the down man, RT veers inside to a backer.
// ---------------------------------------------------------------------------

const EVEN_LINE = {
  Y: block('E-L'),
  LT: LT_RIP,
  LG: block('T-L'),
  RG: block('T-R'),
} satisfies Partial<Record<OffPosId, Action[]>>

// ---------------------------------------------------------------------------
// Front plans
// ---------------------------------------------------------------------------

