export const veerRed: Play = {
  id: 'veer-red',
  name: 'Veer',
  family: 'run',
  formation: 'red',
  direction: 'right',
  ballCarrier: 'S',
  description:
    'Our bread and butter. Super dives at the crack of the playside guard, the quarterback reads one man and gives, keeps, or pitches, and the backside wing motions across to ride in pitch relationship. Three plays in one — the defense picks which one we run.',
  assignments,
  vs: { '44': vs44, '43': vs43, '52': vs52 } satisfies Record<FrontId, FrontPlan>,
  reviewNotes,
}

/**
 * Veer Black — generated by mirroring Veer Red, then checked panel by panel
 * against varsity page 6's left-hand diagrams.
 *
 * Hand corrections after that check: NONE were needed. Both fronts we built
 * are left/right symmetric and Black is drawn on page 1 as an exact mirror of
 * Red, so every rule resolves to the mirrored player with the same job:
 * BSW is now R (motions right-to-left as the pitch man), PSW is now L, PST is
 * LT, the read key becomes E-L (even) / T-L (odd), and X — now split left —
 * still blocks the corner on his side. Note that page 6's bottom two panels
 * are Veer LEFT out of the RED formation (tight end stays left), which is a
 * different play from Veer Black; they were used to confirm the direction
 * logic — dive at the playside guard, keep outside, pitch arcing wide — not
 * the alignment.
 */
export const veerBlack: Play = mirrorPlay(veerRed, {
  id: 'veer-black',
  formation: 'black',
  description:
    'Veer to the left out of Black. Same read, same pitch relationship, other side of the ball — R is the pitch man now and L is the wing who pins.',
  reviewNotes: [
    ...reviewNotes,
    'Veer Black is generated by mirroring Veer Red (app/utils/mirror.ts) with no hand corrections. If any of the Red answers above change, Black changes with it automatically.',
  ],
})

export const veerPlays: Play[] = [veerRed, veerBlack]
